import{_ as r,a0 as o,w as p,s as l,I as t,x as e,a1 as i,A as m,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse(`{"title":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理软件 RAID | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理软件 RAID | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理软件 RAID | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理软件 RAID | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 9 - How to Manage Software RAID's in Linux with 'Mdadm' Tool","title":"在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理软件 RAID","tag":"RAID","desc":""},"relativePath":"RAID/Part 9 - How to Manage Software RAID's in Linux with 'Mdadm' Tool.md","filePath":"[post].md"}`),s={name:"RAID/Part 9 - How to Manage Software RAID's in Linux with 'Mdadm' Tool.md"};function R(u,d,w,A,D,I){const a=o("Link");return p(),l("div",null,[d[21]||(d[21]=t("h1",{id:"在-linux-下使用-raid-九-如何使用-mdadm-工具管理软件-raid",tabindex:"-1"},[e("在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理软件 RAID "),t("a",{class:"header-anchor",href:"#在-linux-下使用-raid-九-如何使用-mdadm-工具管理软件-raid","aria-label":"Permalink to “在 Linux 下使用 RAID（九）：如何使用 ‘Mdadm’ 工具管理软件 RAID”"},"​")],-1)),t("p",null,[d[1]||(d[1]=e("无论你以前有没有使用 RAID 阵列的经验，以及是否完成了 ",-1)),i(a,{href:"https://linux.cn/article-6085-1.html"},{default:m(()=>[...d[0]||(d[0]=[e("此 RAID 系列",-1)])]),_:1}),d[2]||(d[2]=e(" 的所有教程，一旦你在 Linux 中熟悉了 ",-1)),d[3]||(d[3]=t("code",null,"mdadm --manage",-1)),d[4]||(d[4]=e(" 命令的使用，管理软件 RAID 将不是很复杂的任务。",-1))]),d[22]||(d[22]=n(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Manage-Raid-with-Mdadm-Tool-in-Linux.jpg" alt="在 Linux 中使用 mdadm 管理 RAID 设备 - 第9部分"></p><p><em>在 Linux 中使用 mdadm 管理 RAID 设备 - 第9部分</em></p><p>在本教程中，我们会再介绍此工具提供的功能，这样当你需要它，就可以派上用场。</p><h4 id="raid-测试方案" tabindex="-1">RAID 测试方案 <a class="header-anchor" href="#raid-测试方案" aria-label="Permalink to “RAID 测试方案”">​</a></h4><p>在本系列的最后一篇文章中，我们将使用一个简单的 RAID 1（镜像）阵列，它由两个 8GB 的磁盘（/dev/sdb 和 /dev/sdc）和一个备用设备（/dev/sdd）来演示，但在此使用的方法也适用于其他类型的配置。也就是说，放心去用吧，把这个页面添加到浏览器的书签，然后让我们开始吧。</p><h3 id="了解-mdadm-的选项和使用方法" tabindex="-1">了解 mdadm 的选项和使用方法 <a class="header-anchor" href="#了解-mdadm-的选项和使用方法" aria-label="Permalink to “了解 mdadm 的选项和使用方法”">​</a></h3><p>幸运的是，mdadm 有一个内建的 <code>--help</code> 参数来对每个主要的选项提供说明文档。</p><p>因此，让我们开始输入：</p><pre><code># mdadm --manage --help
</code></pre><p>就会使我们看到 <code>mdadm --manage</code> 能够执行哪些任务：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/mdadm-Usage-in-Linux.png" alt="Manage RAID with mdadm Tool"></p><p><em>使用 mdadm 工具来管理 RAID</em></p><p>正如我们在上面的图片看到，管理一个 RAID 阵列可以在任意时间执行以下任务：</p><ul><li>（重新）将设备添加到阵列中</li><li>把设备标记为故障</li><li>从阵列中删除故障设备</li><li>使用备用设备更换故障设备</li><li>先创建部分阵列</li><li>停止阵列</li><li>标记阵列为 ro（只读）或 rw（读写）</li></ul><h3 id="使用-mdadm-工具管理-raid-设备" tabindex="-1">使用 mdadm 工具管理 RAID 设备 <a class="header-anchor" href="#使用-mdadm-工具管理-raid-设备" aria-label="Permalink to “使用 mdadm 工具管理 RAID 设备”">​</a></h3><p>需要注意的是，如果用户忽略 <code>--manage</code> 选项，mdadm 默认使用管理模式。请记住这一点，以避免出现最坏的情况。</p><p>上图中的高亮文本显示了管理 RAID 的基本语法：</p><pre><code># mdadm --manage RAID options devices
</code></pre><p>让我们来演示几个例子。</p><h4 id="​例1-为-raid-阵列添加设备" tabindex="-1">​例1：为 RAID 阵列添加设备 <a class="header-anchor" href="#​例1-为-raid-阵列添加设备" aria-label="Permalink to “​例1：为 RAID 阵列添加设备”">​</a></h4><p>你通常会添加新设备来更换故障的设备，或者使用空闲的分区以便在出现故障时能及时替换：</p><pre><code># mdadm --manage /dev/md0 --add /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Add-Device-to-Raid-Array.png" alt="Add Device to Raid Array"></p><p><em>添加设备到 Raid 阵列</em></p><h4 id="​例2-把一个-raid-设备标记为故障并从阵列中移除" tabindex="-1">​例2：把一个 RAID 设备标记为故障并从阵列中移除 <a class="header-anchor" href="#​例2-把一个-raid-设备标记为故障并从阵列中移除" aria-label="Permalink to “​例2：把一个 RAID 设备标记为故障并从阵列中移除”">​</a></h4><p>在从逻辑阵列中删除该设备前，这是强制性的步骤，然后才能从机器中取出它 - 注意顺序（如果弄错了这些步骤，最终可能会造成实际设备的损害）：</p><pre><code># mdadm --manage /dev/md0 --fail /dev/sdb1
</code></pre>`,27)),t("p",null,[d[6]||(d[6]=e("请注意在前面的例子中，知道如何添加备用设备来自动更换出现故障的磁盘。在此之后，",-1)),i(a,{href:"https://linux.cn/article-6448-1.html"},{default:m(()=>[...d[5]||(d[5]=[e("恢复和重建 raid 数据",-1)])]),_:1}),d[7]||(d[7]=e(" 就开始了：",-1))]),d[23]||(d[23]=n(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Recover-and-Rebuild-Raid-Data.png" alt="Recover and Rebuild Raid Data"></p><p><em>恢复和重建 raid 数据</em></p><p>一旦设备已被手动标记为故障，你就可以安全地从阵列中删除它：</p><pre><code># mdadm --manage /dev/md0 --remove /dev/sdb1
</code></pre><h4 id="例3-重新添加设备-来替代阵列中已经移除的设备" tabindex="-1">例3：重新添加设备，来替代阵列中已经移除的设备 <a class="header-anchor" href="#例3-重新添加设备-来替代阵列中已经移除的设备" aria-label="Permalink to “例3：重新添加设备，来替代阵列中已经移除的设备”">​</a></h4><p>到现在为止，我们有一个工作的 RAID 1 阵列，它包含了2个活动的设备：/dev/sdc1 和 /dev/sdd1。现在让我们试试重新添加 /dev/sdb1 到/dev/md0：</p><pre><code># mdadm --manage /dev/md0 --re-add /dev/sdb1
</code></pre><p>我们会碰到一个错误:</p><pre><code># mdadm: --re-add for /dev/sdb1 to /dev/md0 is not possible
</code></pre><p>因为阵列中的磁盘已经达到了最大的数量。因此，我们有两个选择：a）将 /dev/sdb1 添加为备用的，如例1；或 b）从阵列中删除 /dev/sdd1 然后重新添加 /dev/sdb1。</p><p>我们选择选项 b），先停止阵列然后重新启动：</p><pre><code># mdadm --stop /dev/md0
# mdadm --assemble /dev/md0 /dev/sdb1 /dev/sdc1
</code></pre><p>如果上面的命令不能成功添加 /dev/sdb1 到阵列中，使用例1中的命令来完成。</p><p>mdadm 能检测到新添加的设备并将其作为备用设备，当添加完成后它会开始重建数据，它也被认为是 RAID 中的活动设备：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Raid-Rebuild-Status.png" alt="Raid Rebuild Status"></p><p><em>重建 Raid 的状态</em></p><h4 id="例4-使用特定磁盘更换-raid-设备" tabindex="-1">例4：使用特定磁盘更换 RAID 设备 <a class="header-anchor" href="#例4-使用特定磁盘更换-raid-设备" aria-label="Permalink to “例4：使用特定磁盘更换 RAID 设备”">​</a></h4><p>在阵列中使用备用磁盘更换磁盘很简单：</p><pre><code># mdadm --manage /dev/md0 --replace /dev/sdb1 --with /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Replace-Raid-device.png" alt="Replace Raid Device"></p><p><em>更换 Raid 设备</em></p><p>这会导致 <code>--replace</code> 指定的设备被标记为故障，而 <code>--with</code>指定的设备添加到 RAID 中来替代它：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Check-Raid-Rebuild-Status.png" alt="Check Raid Rebuild Status"></p><p><em>检查 Raid 重建状态</em></p><h4 id="​例5-标记-raid-阵列为-ro-或-rw" tabindex="-1">​例5：标记 RAID 阵列为 ro 或 rw <a class="header-anchor" href="#​例5-标记-raid-阵列为-ro-或-rw" aria-label="Permalink to “​例5：标记 RAID 阵列为 ro 或 rw”">​</a></h4><p>创建阵列后，你必须在它上面创建一个文件系统并将其挂载到一个目录下才能使用它。你可能不知道，RAID 也可以被设置为 ro，使其只读；或者设置为 rw，就可以同时写入了。</p><p>要标记该设备为 ro，首先需要将其卸载：</p><pre><code># umount /mnt/raid1
# mdadm --manage /dev/md0 --readonly
# mount /mnt/raid1
# touch /mnt/raid1/test1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Set-Permissions-on-Raid-Array.png" alt="Set Permissions on Raid Array"></p><p><em>在 RAID 阵列上设置权限</em></p><p>要配置阵列允许写入操作需要使用 <code>--readwrite</code> 选项。请注意，在设置 rw 标志前，你需要先卸载设备并停止它：</p><pre><code># umount /mnt/raid1
# mdadm --manage /dev/md0 --stop
# mdadm --assemble /dev/md0 /dev/sdc1 /dev/sdd1
# mdadm --manage /dev/md0 --readwrite
# touch /mnt/raid1/test2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Allow-Write-Permission-on-Raid.png" alt="Allow Read Write Permission on Raid"></p><p><em>配置 Raid 允许读写操作</em></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在本系列中，我们已经解释了如何建立一个在企业环境中使用的软件 RAID 阵列。如果你按照这些文章所提供的例子进行配置，在 Linux 中你会充分领会到软件 RAID 的价值。</p><p>如果你碰巧任何问题或有建议，请随时使用下面的方式与我们联系。</p><hr>`,38)),t("p",null,[d[9]||(d[9]=e("via: ",-1)),i(a,{href:"http://www.tecmint.com/manage-software-raid-devices-in-linux-with-mdadm/"},{default:m(()=>[...d[8]||(d[8]=[e("http://www.tecmint.com/manage-software-raid-devices-in-linux-with-mdadm/",-1)])]),_:1})]),t("p",null,[d[13]||(d[13]=e("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:m(()=>[...d[10]||(d[10]=[e("GABRIEL CÁNEPA",-1)])]),_:1}),d[14]||(d[14]=e(" 译者：",-1)),i(a,{href:"https://github.com/strugglingyouth"},{default:m(()=>[...d[11]||(d[11]=[e("strugglingyouth",-1)])]),_:1}),d[15]||(d[15]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:m(()=>[...d[12]||(d[12]=[e("wxy",-1)])]),_:1})]),t("p",null,[d[18]||(d[18]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:m(()=>[...d[16]||(d[16]=[e("LCTT",-1)])]),_:1}),d[19]||(d[19]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:m(()=>[...d[17]||(d[17]=[e("Linux中国",-1)])]),_:1}),d[20]||(d[20]=e(" 荣誉推出",-1))])])}const v=r(s,[["render",R]]);export{g as __pageData,v as default};
